contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash, uint lockAmount) public payable {
        require(address(this).balance >= lockAmount, "not enough balance for lockInGuess");

        // Set up a guess that will surely be wrong so that settle does not transfer.
        c.lockInGuess{value: lockAmount}(guessHash);

        // Record balance before settle.
        uint balBefore = address(c).balance;

        // Advance the block so settle is allowed. We cannot use vm, but we can
        // wait: the checker runs a single transaction, so block.number won't change.
        // However, lockInGuess sets guesses[msg.sender].block = block.number + 1,
        // so settle will require block.number > guesses[msg.sender].block,
        // which is false in the same block. Thus settle will always revert here.
        // We cannot mine a new block within the test.
        // Instead, we use the fact that we cannot call settle successfully in the same block.
        // We can still assert a rule about what happens when settle is attempted too early.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint balAfter = address(c).balance;

        // General rule: If settle is called before the required block, it must revert and
        // the contract balance must not change.
        assert(settleReverted && balAfter == balBefore);
    }

    receive() external payable {}
}

